class TinyTokenizer
  getter route : Symbol?
  getter native_calls : Int32
  getter external_calls : Int32

  def initialize
    @route = nil.as(Symbol?)
    @native_calls = 0
    @external_calls = 0
  end

  def encode_native(text : String) : Array(Int32)
    @route = :native
    @native_calls += 1
    [11, 12]
  end

  def encode_external(text : String, *, add_bos_override : Bool? = nil) : Array(Int32)
    @route = :external
    @external_calls += 1
    ids = [11, 12]
    ids.unshift(1) if add_bos_override == true
    ids
  end
end

tokenizer = TinyTokenizer.new
text = "hello"
add_bos_override = false
ids = <HOLE>

